from playwright.sync_api import sync_playwright
from pathlib import Path
with sync_playwright() as p:
 b=p.chromium.launch(args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':800});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content((Path(__file__).resolve().parents[1]/'index.html').read_text());page.wait_for_timeout(200)
 result=page.evaluate('''()=>{let ns=0,as=0,cmp=0,unmatched=0,issues=[],outcomes={ok:0,bad:0};const check=(cond,msg)=>{if(!cond)issues.push(msg)};const coords=()=>Object.fromEntries(['browser','auth','app','server'].map(id=>{let r=document.querySelector(`[data-node="${id}"] rect.node`).getBoundingClientRect();return [id,[r.x,r.y,r.width,r.height]]}));for(const m of ORDER){choose('normal',m);check($('scenario').options.length===1&&$('scenario').value==='login','normal options '+m);let base=coords();for(let i=0;i<steps().length;i++){go(i);ns++;check(!!steps()[i].states.app,'app state '+m+i);check(JSON.stringify(base)===JSON.stringify(coords()),'normal coords '+m+i);}for(const a of Object.keys(ATTACKS).filter(a=>applicable(m,a))){choose('attack',m,a);let list=steps();outcomes[list.at(-1).tone]++;for(let i=0;i<list.length;i++){go(i);as++;let s=list[i],j=normalIndex(m,a,s);check(JSON.stringify(base)===JSON.stringify(coords()),'attack coords '+m+a+i);let attacker=document.querySelector('[data-node="attacker"] rect.node');check(attacker.classList.contains('risk')||!s.actorStarted,'attacker '+m+a+i);if(j<0){unmatched++;check($('stepCompare').disabled,'unmatched '+m+a+i);continue;}cmp++;$('stepCompare').click();check(refView&&STATE.step===i,'compare '+m+a+i);check(JSON.stringify(base)===JSON.stringify(coords()),'compare coords '+m+a+i);$('stepCompare').click();check(!refView&&STATE.step===i,'restore '+m+a+i);}}}return {ns,as,cmp,unmatched,outcomes,issues:issues.slice(0,20),issueCount:issues.length}}''')
 print(result, 'errors',errors)
 assert result['ns']==59 and result['as']==197 and result['cmp']==160 and result['unmatched']==37 and result['outcomes']=={'ok':8,'bad':9} and result['issueCount']==0 and not errors
 b.close()
